import { execFileSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { readFile, mkdir } from 'node:fs/promises'
import { createRequire } from 'node:module'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { build } from 'esbuild'
const root=resolve(dirname(fileURLToPath(import.meta.url)),'..')
const require=createRequire(join(root,'package.json'))
const [mode,inputPath,reviewPath]=process.argv.slice(2)
if(!['inspect','apply'].includes(mode)||!inputPath)throw new Error('USAGE')
const inputBytes=await readFile(resolve(inputPath));const input=JSON.parse(inputBytes.toString('utf8'));const inputSha=hash(inputBytes)
if(input.schemaVersion!==1||input.mediaCount!==17||input.resources?.length!==17||input.resources.some(x=>x.organizationId!==input.organizationId))throw new Error('MEDIA_PACKAGE_INVALID')
const outputBytes=new Map(),objects=[]
for(const item of input.resources){for(const object of item.objects){const bytes=await readFile(resolve('G:/英语资产',object.sourcePath));if(hash(bytes)!==object.sha256||bytes.length!==object.bytes)throw new Error('LOCAL_MEDIA_HASH_MISMATCH');outputBytes.set(object.fileID,bytes);objects.push({...object,bytes})}}
const [scan,sourceScan,negative]=await Promise.all([
 readFile(resolve('G:/英语资产',input.scanEvidence.outputReport),'utf8'),readFile(resolve('G:/英语资产',input.scanEvidence.sourceReport),'utf8'),readFile(resolve('G:/英语资产',input.scanEvidence.negativeControl),'utf8')])
if(!scan.includes('Scanned files: 18')||!scan.includes('Infected files: 0')||!sourceScan.includes('Scanned files: 120')||!sourceScan.includes('Infected files: 0')||!negative.includes('Eicar-Test-Signature FOUND'))throw new Error('SCAN_EVIDENCE_FAILED')
const review=mode==='apply'?JSON.parse(await readFile(resolve(reviewPath),'utf8')):null
if(mode==='apply'&&(!review||review.authorizationScope!=='m3_cip_selected_video_nonproduction'||review.approved!==true||review.inputSha256!==inputSha||review.environmentId!==input.environmentId||JSON.stringify([...review.expectedResourceIds].sort())!==JSON.stringify(input.resources.map(x=>x.resourceId).sort())||JSON.stringify([...review.expectedOrganizationIds].sort())!==JSON.stringify(['org_isolation_secondary','org_qihang_demo'])||!Number.isFinite(Date.parse(review.expiresAt))||Date.parse(review.expiresAt)<=Date.now()))throw new Error('REVIEW_SCOPE_MISMATCH')
const config=JSON.parse(await readFile(join(root,'cloudbaserc.json'),'utf8'));const envText=await readFile(join(root,'.env.local'),'utf8');const envId=envText.split(/\r?\n/u).find(x=>x.startsWith('TCB_ENV_ID='))?.slice(11).trim();if(!envId||config.envId!==envId||input.environmentId!==envId)throw new Error('ENVIRONMENT_MISMATCH')
const cli=resolve('D:/app-cache/cloudbase-cli/node_modules/@cloudbase/cli/bin/tcb')
function cliData(args){const raw=execFileSync(process.execPath,[cli,...args],{cwd:root,encoding:'utf8',windowsHide:true,timeout:30000,maxBuffer:8*1024*1024,stdio:['ignore','pipe','pipe']});const at=raw.indexOf('{');if(at<0)throw new Error('CLOUD_CLI_JSON_MISSING');const value=JSON.parse(raw.slice(at));if(value.error)throw new Error('CLOUD_CLI_ERROR');return value.data}
const environments=cliData(['env','list','--json']);if(environments.length!==1||environments[0].EnvId!==envId||environments[0].Status!=='NORMAL'||environments[0].PackageName!=='个人版'||environments[0].EnvPaid!=='no'||environments[0].EnvCharged!=='no'||environments[0].EnableOverrun!==false)throw new Error('NONPRODUCTION_COST_GATE')
const writeQuota=cliData(['api','tcb','DescribeQuotaData','--api-version','2018-06-08','--body',JSON.stringify({EnvId:envId,MetricName:'DbWritepkg'}),'--json'])
const storageQuota=cliData(['api','tcb','DescribeQuotaData','--api-version','2018-06-08','--body',JSON.stringify({EnvId:envId,MetricName:'StorageSizepkg'}),'--json'])
const newBytes=objects.reduce((n,x)=>n+x.bytes.length,0);if(!Number.isFinite(writeQuota.Value)||writeQuota.Value>190000||!Number.isFinite(storageQuota.Value)||storageQuota.Value+newBytes>4_000_000_000||mode==='apply'&&newBytes>review.maxAdditionalStorageBytes)throw new Error('NONPRODUCTION_QUOTA_GATE')
const acl=execFileSync(process.execPath,[cli,'storage','get-acl','--json'],{cwd:root,encoding:'utf8',windowsHide:true,timeout:30000});if(!acl.includes('Only creator and admin can read and write'))throw new Error('STORAGE_NOT_PRIVATE')
const secret=cliData(['secrets','get','--json']);if(secret?.isTemporary!==true||secret.envId!==envId||Date.parse(secret.expiredAt)<=Date.now()+60000)throw new Error('TEMP_CREDENTIAL_GATE')
const sdk=require('@cloudbase/node-sdk');const app=sdk.init({env:envId,secretId:secret.secretId,secretKey:secret.secretKey,sessionToken:secret.token});const entry=join(root,'.runtime/cip-task-media-v1/entry.cjs');await mkdir(dirname(entry),{recursive:true});await build({entryPoints:[join(root,'src/seed/m3-public-media-entry.ts')],outfile:entry,bundle:true,format:'cjs',platform:'node',target:'node22',logLevel:'silent'});const api=require(entry);const db=api.createCloudBaseDocumentDatabase(app.database())
const organizations=(await db.find('organizations',{status:'active',deletedAt:null})).map(x=>x._id).sort();if(JSON.stringify(organizations)!==JSON.stringify(['org_isolation_secondary','org_qihang_demo']))throw new Error('ORGANIZATION_SCOPE_GATE')
const slotChecks=[];for(const item of input.resources){const proj=`public_media_${hash(Buffer.from(JSON.stringify([item.resourceId,'org_isolation_secondary']))).slice(0,40)}`;const source=await db.get('learning_resources',item.resourceId);const projection=await db.get('learning_resources',proj);if(source||projection)throw new Error('TARGET_DATABASE_SLOT_NOT_EMPTY');slotChecks.push({sourceEmpty:!source,projectionEmpty:!projection})}
const storageChecks=[];for(const object of objects){let existing=null;try{existing=await app.downloadFile({fileID:object.fileID})}catch{};if(existing){const bytes=Buffer.isBuffer(existing.fileContent)?existing.fileContent:Buffer.from(existing.fileContent??'');if(hash(bytes)!==object.sha256)throw new Error('STORAGE_KEY_CONFLICT');storageChecks.push(true)}else storageChecks.push(false)}
if(mode==='inspect'){process.stdout.write(JSON.stringify({mode,environment:'verified_nonproduction',resources:input.resources.length,objects:objects.length,storageExisting:storageChecks.filter(Boolean).length,objectBytes:newBytes,quota:storageQuota.Value,organizationCount:organizations.length,sourceSlotsEmpty:slotChecks.every(x=>x.sourceEmpty),eicarControl:'passed',cloudWrites:0})+'\n');process.exit(0)}
for(let i=0;i<objects.length;i++){const object=objects[i];if(!storageChecks[i]){const uploaded=await app.uploadFile({cloudPath:object.path,fileContent:object.bytes});if(uploaded?.fileID!==object.fileID)throw new Error('UPLOAD_FILEID_MISMATCH')}}
for(const object of objects){const readback=await app.downloadFile({fileID:object.fileID});const bytes=Buffer.isBuffer(readback.fileContent)?readback.fileContent:Buffer.from(readback.fileContent??'');if(hash(bytes)!==object.sha256)throw new Error('STORAGE_READBACK_HASH_MISMATCH')}
const service=new api.PublicMediaDistributionService(db,{nowIso:()=>new Date().toISOString()});const imports=[]
for(const item of input.resources){const media={...item.processedMedia};const verified={resourceId:item.resourceId,organizationId:item.organizationId,contentVersion:item.contentVersion,manifestSha256:item.manifestSha256,reviewId:item.reviewId,importedBy:item.importedBy,grade:item.grade,sourceSha256:item.sourceSha256,verifiedAt:item.verifiedAt,releaseMode:item.releaseMode,processedMedia:media};api.buildVerifiedCentralMediaResource(verified);const result=await service.importVerified(verified);imports.push({resourceId:item.resourceId,projectedOrganizations:result.projectedOrganizations})}
const readbacks=[];for(const item of input.resources){const source=await db.get('learning_resources',item.resourceId);const projectionId=`public_media_${hash(Buffer.from(JSON.stringify([item.resourceId,'org_isolation_secondary']))).slice(0,40)}`;const projection=await db.get('learning_resources',projectionId);const sourceAudit=await db.get('operation_logs',`public_media_import_${item.resourceId}`);const projectionAudit=await db.get('operation_logs',`public_media_projection_${projectionId}`);if(!source||!projection||!sourceAudit||!projectionAudit||source.status!=='published'||projection.status!=='published'||source.payload?.teacherMedia?.mediaSha256!==item.processedMedia.mediaSha256||source.payload?.assetLibrary?.reviewStatus!=='source_verified_reusable')throw new Error('MEDIA_DATABASE_READBACK_FAILED');readbacks.push({resourceId:item.resourceId,sourcePublished:true,secondaryProjection:true})}
const contentBundle=join(root,'.runtime/cip-task-media-v1/content.cjs');await build({entryPoints:[join(root,'src/seed/m3-real-sample-entry.ts')],outfile:contentBundle,bundle:true,format:'cjs',platform:'node',target:'node22',logLevel:'silent'});const ca=require(contentBundle),catalog=new ca.TeacherAssetCatalogService(db,ca.createOrgContentDocumentRepository(db),undefined,{nowIso:()=>new Date().toISOString()});const teacher={requestId:'cip_video_catalog_20261013',sessionId:'cip-grade6-virtual',actorUserId:'usr_teacher_demo_01',actorRole:'teacher',organizationId:'org_qihang_demo',platformSubjectDigest:'cip-grade6-virtual',permissions:['content.read','task.publish'],scopeIds:['cls_grade4_1'],authzVersion:1};const catalogRows=[]
for(const bookTitle of ['漫画用英语介绍中国地理','漫画用英语介绍中国文化']){const listed=await catalog.list(teacher,{kind:'video',keyword:bookTitle},{limit:50,offset:0});catalogRows.push({bookTitle,count:listed.items.filter(x=>input.resources.some(y=>y.resourceId===x.id)).length})}
if(catalogRows.some(x=>x.count===0))throw new Error('TEACHER_CATALOG_READBACK_FAILED')
process.stdout.write(JSON.stringify({mode,status:'verified_nonproduction',importedSources:imports.length,organizationProjections:imports.reduce((n,x)=>n+x.projectedOrganizations.length,0),storageReadbacks:objects.length,databaseReadbacks:readbacks.length,teacherCatalogRows:catalogRows,productionPublished:false})+'\n');process.exit(0)
function hash(bytes){return createHash('sha256').update(bytes).digest('hex')}
